check_code:
def enc(w): return ''.join(str(27-(ord(c)-64)) for c in w)
assert enc('CYCLE')=='242241522' and enc('FINAL')=='2118132615'
opts={'A':'14681824','B':'1421191824','C':'146191824','D':'146192184'}
r=enc('MUSIC')
assert [k for k,v in opts.items() if v==r]==['A']

opts={'A':'TVX','B':'HJL','C':'MOP','D':'NPR'}
g={k:(ord(v[1])-ord(v[0]),ord(v[2])-ord(v[1])) for k,v in opts.items()}
odd=[k for k in g if list(g.values()).count(g[k])==1]
assert odd==['C']

p='PANTHER';pc='0146283';a='ANOTHER';ac='2864109'
assert set(pc)&set(ac)=={'0','1','2','4','6','8'}
o=(set(ac)-set(pc)).pop()
opts={'A':'3','B':'8','C':'0','D':'9'}
assert [k for k,v in opts.items() if v==o]==['D']

def f(w):
    s=[-2,-2,2,2];return ''.join(chr(ord(c)+d) for c,d in zip(w,s))
assert f('MPQO')=='KNSQ' and f('DGHF')=='BEJH'
opts={'A':'CHQY','B':'BHQX','C':'BGPX','D':'CGPY'}
assert [k for k,v in opts.items() if v==f('EINW')]==['D']

young={('Larva','Insect'),('Fawn','Deer')}
opts={'A':('Dog','Animal'),'B':('Fawn','Deer'),'C':('Fox','Vixen'),'D':('Bat','Chick')}
assert [k for k,v in opts.items() if v in young]==['B']

r=49/7+6*8-13
opts={'A':42,'B':37,'C':43,'D':32}
assert [k for k,v in opts.items() if v==r]==['A']

w='DRAFTING';n=sum(a==b for a,b in zip(w,sorted(w)))
opts={'A':0,'B':1,'C':3,'D':2}
assert [k for k,v in opts.items() if v==n]==['A']

def fill(o):
    t=list('I__I_I__I_J_');it=iter(o.split())
    return ''.join(next(it) if c=='_' else c for c in t)
opts={'A':'J I J I J I I','B':'J I I I J J I','C':'I J I I J J I','D':'I I J J J I J'}
ok=[k for k,v in opts.items() if fill(v)=='IJI'*4]
assert ok==['A']
